select 'Handong Global University','South Korea','Private','University','Pohang','https://www.handong.edu/eng/',false,false,'{"ug": "Handong Global University is a private Christian university in Pohang. Its 2027 admission guideline for international students says four majors are taught 100% in English (listed here); its other majors are partly in Korean. English scores (TOEFL iBT 85, IELTS 5.5 or New TEPS 285) are recommended, not required; without one, English is checked at the interview. Tuition per semester: KRW 4,023,000 (first semester) and 3,843,000 (second semester) in year 1; from year 2 KRW 3,171,000 to 4,068,000 depending on the double major. Rounds for 2027: 1 August to 15 September 2026 (spring entry) and 1 February to 15 March 2027 (fall entry).", "sources": ["https://www.handong.edu/ext/bbs/download.dcp?id=16397"]}'::jsonb,'https://www.handong.edu/ext/bbs/download.dcp?id=16397',date '2026-11-28'
where not exists (select 1 from public.schools where name='Handong Global University' and country='South Korea');
