select 'Beijing Normal-Hong Kong Baptist University (BNBU)','China','Private','University','Zhuhai','https://www.bnbu.edu.cn/en/',false,false,'{"ug": "Beijing Normal-Hong Kong Baptist University (BNBU, formerly BNU-HKBU United International College) in Zhuhai was set up by Beijing Normal University and Hong Kong Baptist University. Its international admissions page says all programmes are taught in English. Fees and English requirements are on separate pages that were not read.", "sources": ["https://admission.bnbu.edu.cn/ido/programmes_courses.htm"]}'::jsonb,'https://admission.bnbu.edu.cn/ido/programmes_courses.htm',date '2026-11-28'
where not exists (select 1 from public.schools where name='Beijing Normal-Hong Kong Baptist University (BNBU)' and country='China');
insert into public.schools(name,country,type,category,city,website,verified,demo,admission_info,admission_link,admission_checked)
select 'Beijing Institute of Technology','China','Public','University','Beijing','https://isc.bit.edu.cn/',false,false,'{"ug": "Beijing Institute of Technology''s admission book for international undergraduates lists these programmes as taught in English (eight at the Beijing campus, Artificial Intelligence at the Zhuhai campus); its other undergraduate programmes are taught in Chinese. English-taught applicants need TOEFL 85 or IELTS 6.0 (native speakers and graduates of English-medium high schools are exempt). The book read was the 2026 edition; the tuition table in it was unclear, so no fee is shown here.", "sources": ["https://isc.bit.edu.cn/docs//2025-11/b59c4c1d2b41494f9e2edc2c0993742b.pdf"]}'::jsonb,'https://isc.bit.edu.cn/docs//2025-11/b59c4c1d2b41494f9e2edc2c0993742b.pdf',date '2026-11-28'
where not exists (select 1 from public.schools where name='Beijing Institute of Technology' and country='China');

