join public.schools sc on sc.name=v.sname and sc.country=v.country
where not exists (select 1 from public.programs p where p.school_id=sc.id and p.name=v.pname and p.level='Undergraduate');

commit;

refresh materialized view public.program_groups;
refresh materialized view public.program_group_counts;
refresh materialized view public.program_field_counts;
analyze public.program_groups;

-- Check: schools and programmes per country (before: Japan 27 / 125, South Korea 11 / 55, China 14 / 159; expected after: Japan 39 / 152, South Korea 12 / 59, China 17 / 218)
select s.country, count(distinct s.id) schools, count(p.id) programmes from public.schools s left join public.programs p on p.school_id=s.id
where s.country in ('Japan','South Korea','China') group by s.country order by s.country;
